"use client";

import { useCallback, useEffect, useId, useRef, useState, type FormEvent, type ReactNode, type RefObject } from "react";

import { IconAlertCircle } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { DateField } from "@rhs-ui/primitives/date-field";
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@rhs-ui/primitives/dialog";
import { isTyping, matchesShortcut, parseShortcut, shortcutKeys } from "@rhs-ui/primitives/go-to-dialog/shortcut";
import { articleFor, checkNumber, dayHint, DEFAULT_LABELS, fillIn, numberHint, type GoToKind, type GoToLabels, type GoToValue } from "@rhs-ui/primitives/go-to-dialog/validate";
import { Input } from "@rhs-ui/primitives/input";
import { Kbd, KbdGroup } from "@rhs-ui/primitives/kbd";
import { cn } from "@/lib/utils";

export type { GoToKind, GoToLabels, GoToValue } from "@rhs-ui/primitives/go-to-dialog/validate";

export interface GoToDialogProps<K extends GoToKind = "number"> {
  /** What to ask for: a whole `number` (a page, a line, a row) or a calendar `date`. Default "number". */
  kind?: K;
  /** The lowest value that can be used: a number, or an ISO date such as `2026-03-14` for a date. A number starts at 1. */
  min?: GoToValue<K>;
  /** The highest value that can be used, in the same form. */
  max?: GoToValue<K>;
  /** What the field starts with, usually where you are now. A number is selected when the dialog opens, so typing replaces it. */
  defaultValue?: GoToValue<K>;
  /** The title of the dialog and the name of the field: "Go to page". Default "Go to {noun}". */
  label?: string;
  /** What is being picked, for the messages: "page", "line", "row". Default "number", or "date" for a date. */
  noun?: string;
  /** The locale that writes numbers and decides the order of day, month and year in a date. Default "en-US". */
  locale?: string;
  /** Called with the value once Go (or Enter) was chosen, the dialog has closed and focus has been given back, so you can move focus to where you went. */
  onGo: (value: GoToValue<K>) => void;
  /** The keys that open it from anywhere on the page, as `mod+g` (Command on a Mac, Control elsewhere). Pass `false` for none. It is left alone while someone types in another field or another dialog is open. Default "mod+g". */
  shortcut?: string | false;
  /** The element that opens it, usually a Button. Without one it opens with the shortcut or through `open`. */
  trigger?: ReactNode;
  /** Whether it is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The words the dialog says, for translation. */
  labels?: Partial<GoToLabels>;
  /** Classes for the panel, for a different width. */
  className?: string;
}

/** Red text on the pale red of a message: the destructive colour pulled toward the text colour keeps 4.5 to 1 in both themes. */
const ERROR_TEXT = "text-[color-mix(in_oklch,var(--destructive),var(--foreground)_20%)]";

const isApple = () => typeof navigator !== "undefined" && /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent);

interface GoToFormProps {
  kind: GoToKind;
  min?: number | string;
  max?: number | string;
  start?: number | string;
  locale: string;
  noun: string;
  title: string;
  labels: GoToLabels;
  fieldId: string;
  fieldRef: RefObject<HTMLInputElement | null>;
  keys: string[] | null;
  onSubmit: (value: number | string) => void;
}

/** The question itself. It mounts when the dialog opens, so every opening starts from the default value with no old message. */
function GoToForm({ kind, min, max, start, locale, noun, title, labels, fieldId, fieldRef, keys, onSubmit }: GoToFormProps) {
  const noteId = useId();
  const [text, setText] = useState(start === undefined ? "" : String(start));
  const [iso, setIso] = useState(typeof start === "string" ? start : "");
  const [tried, setTried] = useState(false);
  const [incomplete, setIncomplete] = useState(false);

  const isDate = kind === "date";
  const lower = typeof min === "number" ? min : 1;
  const upper = typeof max === "number" ? max : undefined;
  const check = checkNumber(text, { min: lower, max: upper, locale, noun, labels });
  const empty = fillIn(labels.empty, { noun, article: articleFor(noun) });
  const problem = isDate ? (incomplete ? empty : null) : check.state === "invalid" ? check.message : tried && check.state === "empty" ? empty : null;
  const hint = isDate ? dayHint({ min: typeof min === "string" ? min : undefined, max: typeof max === "string" ? max : undefined, locale, labels }) : numberHint({ min: lower, max: upper, locale, labels });

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    // The dialog is drawn in a portal, but React still passes its events up to the component that rendered it: a dialog opened from inside a form must not submit that form too.
    event.stopPropagation();
    if (isDate) {
      if (iso) {
        onSubmit(iso);
        return;
      }
      // A date that is complete but impossible already has its reason under the field; only a date that is not finished needs ours.
      const parts = event.currentTarget.querySelectorAll<HTMLInputElement>('[data-slot="date-field"] input[role="spinbutton"]');
      setIncomplete(Array.from(parts).some((part) => part.value === ""));
      document.getElementById(fieldId)?.focus();
      return;
    }
    if (check.state === "valid") {
      onSubmit(check.value);
      return;
    }
    setTried(true);
    fieldRef.current?.focus();
  }

  /** The arrow keys step the number, and Shift steps by ten. */
  function step(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    event.preventDefault();
    const base = check.state === "valid" ? check.value : lower;
    const next = base + (event.shiftKey ? 10 : 1) * (event.key === "ArrowUp" ? 1 : -1);
    setText(String(Math.min(upper ?? Number.MAX_SAFE_INTEGER, Math.max(lower, next))));
    setTried(false);
  }

  return (
    <form onSubmit={submit} noValidate className="grid gap-5">
      <DialogHeader className="gap-1">
        <DialogTitle className="text-base tracking-[-0.01em]">
          {title}
        </DialogTitle>
        <DialogDescription className="sr-only">{labels.description}</DialogDescription>
      </DialogHeader>

      {/* A date field says what is wrong with a date by itself, in the line under it: that line takes the place of the hint, and the note area stays one line. */}
      <div className={cn("grid gap-2", isDate && "[&:has([data-slot=date-field]_p)>[data-slot=go-to-note]]:hidden [&_[data-slot=date-field]_p]:mt-2")}>
        {isDate ? (
          <DateField
            // As wide as the dialog, like the number field.
            className="[&_[data-slot=input-group]]:w-full"
            id={fieldId}
            aria-label={title}
            aria-describedby={noteId}
            value={iso}
            onValueChange={(next) => {
              setIso(next);
              setIncomplete(false);
            }}
            locale={locale}
            min={typeof min === "string" ? min : undefined}
            max={typeof max === "string" ? max : undefined}
          />
        ) : (
          <Input
            ref={fieldRef}
            id={fieldId}
            type="text"
            inputMode="numeric"
            enterKeyHint="go"
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            aria-label={title}
            aria-describedby={noteId}
            aria-invalid={problem ? true : undefined}
            value={text}
            onChange={(event) => {
              setText(event.target.value);
              setTried(false);
            }}
            onKeyDown={step}
            // 16px keeps iOS from zooming into the field, and a taller field is the one thing on this dialog.
            className="h-11 px-3.5 text-base tabular-nums"
          />
        )}
        {/* One line, always: the range as a hint, or what is wrong in its place. It is polite, so a change is said once. */}
        <div id={noteId} data-slot="go-to-note" aria-live="polite" className="min-h-4 text-xs leading-4">
          {problem ? (
            <p className={cn("flex items-start gap-1.5", ERROR_TEXT)}>
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {problem}
            </p>
          ) : hint ? (
            <p className="text-muted-foreground tabular-nums">{hint}</p>
          ) : null}
        </div>
      </div>

      <DialogFooter className={cn("items-stretch sm:items-center", keys ? "sm:justify-between" : "sm:justify-end")}>
        {keys ? (
          <span className="hidden items-center gap-2 text-xs text-muted-foreground sm:inline-flex">
            {labels.shortcut}
            <KbdGroup>
              {keys.map((key) => (
                <Kbd key={key}>{key}</Kbd>
              ))}
            </KbdGroup>
          </span>
        ) : null}
        <div className="flex flex-col-reverse gap-2 sm:flex-row">
          <DialogClose asChild>
            <Button type="button" variant="outline">
              {labels.cancel}
            </Button>
          </DialogClose>
          <Button type="submit">{labels.go}</Button>
        </div>
      </DialogFooter>
    </form>
  );
}

/**
 * Jump to a page, line, row or date from the keyboard: a dialog with one field, opened by a shortcut (Command or
 * Control with G) or by a trigger. The field shows the range as its hint ("1 to 240") and checks what is typed as it
 * is typed, naming the problem in words ("Pick a page between 1 and 240"), the arrow keys step a number, Enter goes and
 * closes, and Escape cancels. A number is selected when the dialog opens, so typing replaces it; a date is the
 * library's own date field, in the order the locale writes it. Focus goes back to where it was before the dialog
 * opened, and only then is `onGo` called, so the place you jump to can take focus. The shortcut is left alone while
 * someone is typing in another field, and while another dialog is open, so it never takes a key from a form.
 */
export function GoToDialog<K extends GoToKind = "number">({
  kind,
  min,
  max,
  defaultValue,
  label,
  noun,
  locale = "en-US",
  onGo,
  shortcut = "mod+g",
  trigger,
  open,
  defaultOpen = false,
  onOpenChange,
  labels,
  className,
}: GoToDialogProps<K>) {
  const isDate = kind === "date";
  const word = noun ?? (isDate ? "date" : "number");
  const words = { ...DEFAULT_LABELS, ...labels };
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  const fieldId = useId();
  const field = useRef<HTMLInputElement | null>(null);
  /** Where focus was before the dialog opened. */
  const returnTo = useRef<HTMLElement | null>(null);
  /** The value that was chosen, handed to `onGo` once the dialog has let go of focus. */
  const chosen = useRef<{ value: GoToValue<K> } | null>(null);
  const fallback = useRef<number | undefined>(undefined);
  const latest = useRef({ onGo, onOpenChange, open });
  useEffect(() => {
    latest.current = { onGo, onOpenChange, open };
  });

  const change = useCallback((next: boolean) => {
    if (latest.current.open === undefined) setOwnOpen(next);
    latest.current.onOpenChange?.(next);
  }, []);

  const flush = useCallback(() => {
    window.clearTimeout(fallback.current);
    const go = chosen.current;
    chosen.current = null;
    if (go) latest.current.onGo(go.value);
  }, []);

  useEffect(() => () => window.clearTimeout(fallback.current), []);

  useEffect(() => {
    if (shortcut === false) return;
    const combo = parseShortcut(shortcut);
    function onKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented || event.repeat || !matchesShortcut(event, combo)) return;
      // Typing in a field, or a modal already open (Radix locks the page's scroll for one): not the moment for a dialog.
      if (isTyping(event.target) || document.body.hasAttribute("data-scroll-locked")) return;
      event.preventDefault();
      change(true);
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [shortcut, change]);

  return (
    <Dialog open={isOpen} onOpenChange={change}>
      {trigger ? <DialogTrigger asChild>{trigger}</DialogTrigger> : null}
      <DialogContent
        data-slot="go-to-dialog"
        showCloseButton={false}
        onOpenAutoFocus={(event) => {
          // Radix would focus the first control; this one knows which control is the field, and notes where focus was.
          event.preventDefault();
          const active = document.activeElement;
          returnTo.current = active instanceof HTMLElement && active !== document.body ? active : null;
          const target = isDate ? document.getElementById(fieldId) : field.current;
          target?.focus();
          if (target instanceof HTMLInputElement) target.select();
        }}
        onCloseAutoFocus={(event) => {
          const back = returnTo.current;
          returnTo.current = null;
          // Back to where the person was, not only to the trigger; then, and only then, the jump.
          if (back?.isConnected) {
            event.preventDefault();
            back.focus({ preventScroll: true });
          }
          // After this handler returns Radix still moves focus to the trigger when it was not told not to; the jump comes after that, so it can take focus away again.
          window.setTimeout(flush, 0);
        }}
        className={cn("gap-0 p-5 sm:max-w-sm", className)}
      >
        <GoToForm
          kind={isDate ? "date" : "number"}
          min={min}
          max={max}
          start={defaultValue}
          locale={locale}
          noun={word}
          title={label ?? `Go to ${word}`}
          labels={words}
          fieldId={fieldId}
          fieldRef={field}
          keys={shortcut === false ? null : shortcutKeys(parseShortcut(shortcut), isApple())}
          onSubmit={(value) => {
            chosen.current = { value: value as GoToValue<K> };
            change(false);
            // The dialog hands focus back after its exit; if it is removed before that, the jump still happens.
            fallback.current = window.setTimeout(flush, 800);
          }}
        />
      </DialogContent>
    </Dialog>
  );
}

/**
 * The keyboard shortcut of the go-to dialog, as plain functions with no state and no hook: `mod+g` is read once,
 * matched against key presses, and written out as the keys to show ("Ctrl" and "G", or the command sign and "G").
 */

export interface ShortcutCombo {
  /** The key itself, in lower case: "g". */
  key: string;
  /** Command on a Mac, Control everywhere else: either of them counts. */
  mod: boolean;
  /** Control itself is required, whichever system this is. */
  ctrl: boolean;
  /** Command (or the Windows key) itself is required. */
  meta: boolean;
  /** Alt, called Option on a Mac, is required. */
  alt: boolean;
  /** Shift is required. */
  shift: boolean;
}

/** Reads a shortcut written as `mod+g`, `ctrl+shift+k` or `alt+/`. `mod` is Command on a Mac and Control elsewhere. */
export function parseShortcut(shortcut: string): ShortcutCombo {
  const parts = shortcut
    .toLowerCase()
    .split("+")
    .map((part) => part.trim())
    .filter(Boolean);
  const key = parts.pop() ?? "";
  return {
    key,
    mod: parts.includes("mod"),
    ctrl: parts.includes("ctrl") || parts.includes("control"),
    meta: parts.includes("meta") || parts.includes("cmd") || parts.includes("command"),
    alt: parts.includes("alt") || parts.includes("option"),
    shift: parts.includes("shift"),
  };
}

/** Whether a key press is exactly this shortcut: the key, the modifiers it names and no others. */
export function matchesShortcut(event: Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "altKey" | "shiftKey">, combo: ShortcutCombo): boolean {
  if (!combo.key || event.key.toLowerCase() !== combo.key) return false;
  const modifiers = combo.mod ? event.ctrlKey || event.metaKey : event.ctrlKey === combo.ctrl && event.metaKey === combo.meta;
  return modifiers && event.altKey === combo.alt && event.shiftKey === combo.shift;
}

/** The signs a Mac draws for its modifier keys, written as escapes so no tool can change them. */
const COMMAND = "\u2318";
const OPTION = "\u2325";
const SHIFT = "\u21e7";

/** The keys to draw for a shortcut, in the order people read them: `["Ctrl", "G"]`, or on a Mac the command sign and `"G"`. */
export function shortcutKeys(combo: ShortcutCombo, apple: boolean): string[] {
  const keys: string[] = [];
  if (combo.mod || combo.ctrl) keys.push(combo.mod && apple ? COMMAND : "Ctrl");
  if (combo.alt) keys.push(apple ? OPTION : "Alt");
  if (combo.shift) keys.push(apple ? SHIFT : "Shift");
  if (combo.meta && !combo.mod) keys.push(apple ? COMMAND : "Win");
  keys.push(combo.key.length === 1 ? combo.key.toUpperCase() : combo.key.charAt(0).toUpperCase() + combo.key.slice(1));
  return keys;
}

/** True when the key press is going into a field the person is typing in, where a shortcut must not take it. */
export function isTyping(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable || target.tagName === "TEXTAREA" || target.tagName === "SELECT") return true;
  return target instanceof HTMLInputElement && !["button", "checkbox", "radio", "range", "submit", "reset", "color", "file", "image"].includes(target.type);
}

/**
 * What the go-to dialog checks and says, as plain functions with no state and no hook, so a Server Component can run
 * the same check on a value that came back in a request.
 */

/** What the dialog asks for: a whole number (a page, a line, a row) or a calendar date. */
export type GoToKind = "number" | "date";

/** What `onGo` receives for each kind: a number for `number`, an ISO date such as `2026-03-14` for `date`. */
export type GoToValue<K extends GoToKind = GoToKind> = K extends "date" ? string : number;

/** The words the dialog says, for another language or your own wording. `{min}`, `{max}`, `{noun}` and `{article}` are filled in. */
export interface GoToLabels {
  /** The button that goes. Default "Go". */
  go: string;
  /** The button that closes without going. Default "Cancel". */
  cancel: string;
  /** The hint under the field when there are two limits. Default "{min} to {max}". */
  range: string;
  /** The hint when there is a lower limit only. Default "{min} or more". */
  atLeast: string;
  /** The hint when there is an upper limit only, which only a date can have. Default "Up to {max}". */
  atMost: string;
  /** Said when Go is pressed with nothing typed. Default "Enter {article} {noun}." */
  empty: string;
  /** Said when the text is not a whole number. Default "Use whole numbers only." */
  whole: string;
  /** Said when a number is outside two limits. Default "Pick {article} {noun} between {min} and {max}." */
  between: string;
  /** Said when a number is below the lower limit and there is no upper one. Default "Pick {article} {noun} of {min} or more." */
  below: string;
  /** The label of the shortcut hint in the footer. Default "Shortcut". */
  shortcut: string;
  /** What a screen reader hears after the title. Default "Press Enter to go, or Escape to cancel." */
  description: string;
}

export const DEFAULT_LABELS = {
  go: "Go",
  cancel: "Cancel",
  range: "{min} to {max}",
  atLeast: "{min} or more",
  atMost: "Up to {max}",
  empty: "Enter {article} {noun}.",
  whole: "Use whole numbers only.",
  between: "Pick {article} {noun} between {min} and {max}.",
  below: "Pick {article} {noun} of {min} or more.",
  shortcut: "Shortcut",
  description: "Press Enter to go, or Escape to cancel.",
} satisfies GoToLabels;

/** Puts values into the `{name}` places of a sentence. A place without a value is left as it is. */
export function fillIn(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => values[key] ?? match);
}

/** "a" or "an" for a noun in English: "a page", "an invoice". Other languages write their own sentence in `labels`. */
export function articleFor(noun: string): "a" | "an" {
  return /^[aeiou]/i.test(noun.trim()) ? "an" : "a";
}

/** A number in the locale: "1,240" in en-US, "1.240" in de-DE. */
export function formatWhole(value: number, locale: string): string {
  try {
    return new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(value);
  } catch {
    return String(value);
  }
}

/** An ISO date as it is written in the locale: "14 March 2026". Read as a calendar day, so the time zone never moves it. */
export function formatDay(iso: string, locale: string): string {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso.trim());
  if (!match) return iso;
  const at = Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12);
  try {
    return new Intl.DateTimeFormat(locale, { dateStyle: "long", timeZone: "UTC" }).format(at);
  } catch {
    return new Intl.DateTimeFormat("en-US", { dateStyle: "long", timeZone: "UTC" }).format(at);
  }
}

/** The character a locale puts between groups of thousands, or an empty string when it has none. */
function groupSeparator(locale: string): string {
  try {
    return new Intl.NumberFormat(locale).formatToParts(1_000_000).find((part) => part.type === "group")?.value ?? "";
  } catch {
    return ",";
  }
}

/** Digits typed on a keyboard that writes them differently (Arabic-Indic, Persian) as the digits 0 to 9. */
function asciiDigits(text: string): string {
  return text.replace(/[\u0660-\u0669\u06F0-\u06F9]/g, (char) => String(char.charCodeAt(0) >= 0x6f0 ? char.charCodeAt(0) - 0x6f0 : char.charCodeAt(0) - 0x660));
}

/** A whole number from what was typed, with the locale's thousands separator and spaces allowed ("1,240"), or null when it is anything else. */
export function readWhole(text: string, locale: string): number | null {
  // `\s` covers the no-break spaces some locales put between thousands.
  let cleaned = asciiDigits(text).replace(/\s/g, "");
  const group = groupSeparator(locale).replace(/\s/g, "");
  if (group) cleaned = cleaned.split(group).join("");
  return /^\d{1,15}$/.test(cleaned) ? Number(cleaned) : null;
}

export type NumberCheck = { state: "empty" } | { state: "invalid"; message: string } | { state: "valid"; value: number };

export interface NumberCheckOptions {
  /** The lowest number that can be used. Default 1. */
  min?: number;
  /** The highest number that can be used. */
  max?: number;
  /** The locale for reading and writing numbers. Default "en-US". */
  locale?: string;
  /** What is being picked: "page", "line", "row". Default "number". */
  noun?: string;
  /** Other words for the messages. */
  labels?: Partial<GoToLabels>;
}

/** The hint that shows the range: "1 to 240". */
export function numberHint({ min = 1, max, locale = "en-US", labels }: NumberCheckOptions): string {
  const words = { ...DEFAULT_LABELS, ...labels };
  const values = { min: formatWhole(min, locale), max: max === undefined ? "" : formatWhole(max, locale) };
  return fillIn(max === undefined ? words.atLeast : words.range, values);
}

/** The hint under a date field: "3 March 2026 to 28 October 2026", with whichever limits there are. Null with none. */
export function dayHint({ min, max, locale = "en-US", labels }: { min?: string; max?: string; locale?: string; labels?: Partial<GoToLabels> }): string | null {
  const words = { ...DEFAULT_LABELS, ...labels };
  const values = { min: min ? formatDay(min, locale) : "", max: max ? formatDay(max, locale) : "" };
  if (min && max) return fillIn(words.range, values);
  if (min) return fillIn(words.atLeast, values);
  if (max) return fillIn(words.atMost, values);
  return null;
}

/**
 * Reads what was typed and says what is wrong with it, in words, or gives the number. Nothing typed is `empty`, which is
 * not an error until someone presses Go.
 */
export function checkNumber(text: string, options: NumberCheckOptions = {}): NumberCheck {
  const { min = 1, max, locale = "en-US", noun = "number", labels } = options;
  if (!text.trim()) return { state: "empty" };
  const words = { ...DEFAULT_LABELS, ...labels };
  const values = { min: formatWhole(min, locale), max: max === undefined ? "" : formatWhole(max, locale), noun, article: articleFor(noun) };
  const value = readWhole(text, locale);
  if (value === null) return { state: "invalid", message: fillIn(words.whole, values) };
  if (value < min || (max !== undefined && value > max)) {
    return { state: "invalid", message: fillIn(max === undefined ? words.below : words.between, values) };
  }
  return { state: "valid", value };
}
